import {parsePageRoute,safeNextPath} from './routes.js';
import {initWarehouses,refreshWarehouses,openWarehouseView} from './warehouses.js';
import {authProvider,warehouseRepository,templateRepository,createSaveQueue} from './auth-client.js';
const $=s=>document.querySelector(s);let register=false,busy=false,queue=null,routeGeneration=0;
function message(text){$('#authError').textContent=text}function setBusy(value){busy=value;$('#authSubmit').disabled=value;$('#authSwitch').disabled=value;$('#authSubmit').innerHTML=value?'Please wait…':register?'Create account <span>→</span>':'Log in <span>→</span>'}
async function enter(user){const desired=requestedPageRoute();window.wsmsRouting=true;$('#application').inert=true;window.wsmsSession={user,document:null,warehouse:null};window.wsmsSaveLayout=()=>{};window.wsmsTemplates=[];window.wsmsLoadTemplates=async()=>{window.wsmsTemplates=await templateRepository.list();return window.wsmsTemplates};window.wsmsSaveRackTemplate=async type=>{const record=await templateRepository.saveRack(window.wsmsSession.warehouse.id+':'+type.id,type);window.wsmsTemplates=[record,...window.wsmsTemplates.filter(t=>t.id!==record.id)];return record};$('#accountEmail').textContent=user.email;$('#accountDropdownEmail').textContent=user.email;$('#authLanding').hidden=true;$('#application').hidden=false;await import('./app.js');window.wsmsShowPage('warehouses');window.wsmsRefreshWarehouses=refreshWarehouses;await initWarehouses({beforeOpen:async()=>{await queue?.flush()},async onOpen(data,destination){const warehouse=data.warehouse;window.wsmsOpenWarehouse(data,destination);queue=warehouse.role==='viewer'?null:createSaveQueue(warehouseRepository.layout(warehouse.id),(status,error)=>{const failed=status==='error';$('#saveNotice').hidden=!failed;$('#saveNoticeMessage').textContent=failed?'Changes have not been saved: '+error.message:''});window.wsmsSaveLayout=document=>queue?.schedule(document);$('#legacyNotice').hidden=!!data.document||warehouse.role==='viewer'||!['5','4','3','2','1'].some(v=>localStorage.getItem('warehouse-studio-v'+v))},onDetails(w){window.wsmsUpdateWarehouse?.(w)}});await navigatePageRoute(desired);}
$('#authSwitch').onclick=()=>{if(busy)return;register=!register;message('');$('#authTitle').textContent=register?'Create your workspace':'Log in to your workspace';$('#authSubtitle').textContent=register?'Start planning your warehouse with a free account.':'Your layouts, floors and capacity — all in one place.';$('#confirmLabel').hidden=!register;$('#confirmPassword').required=register;$('#authPassword').autocomplete=register?'new-password':'current-password';$('#authSwitchText').textContent=register?'Already have an account?':'New to WSMS?';$('#authSwitch').textContent=register?'Log in':'Create an account';setBusy(false);};
$('#authForm').onsubmit=async e=>{e.preventDefault();if(busy)return;message('');const email=$('#authEmail').value.trim(),password=$('#authPassword').value;if(register&&password!==$('#confirmPassword').value){message('Passwords do not match.');return}setBusy(true);try{const user=await (register?authProvider.register(email,password):authProvider.login(email,password));await enter(user);$('#authPassword').value='';$('#confirmPassword').value=''}catch(error){message(error.message)}finally{window.wsmsRouting=false;$('#application').inert=false;setBusy(false)}};
$('#accountButton').onclick=()=>{const open=$('#accountDropdown').hidden;$('#accountDropdown').hidden=!open;$('#accountButton').setAttribute('aria-expanded',String(open))};document.addEventListener('click',e=>{if(!e.target.closest('.accountMenu')){$('#accountDropdown').hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#accountDropdown').hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});
$('#logoutButton').onclick=async()=>{const b=$('#logoutButton');b.disabled=true;try{await queue?.flush();await authProvider.logout();if(window.location)window.location.replace('/login');else location.reload()}catch(e){$('#saveNotice').hidden=false;$('#saveNoticeMessage').textContent='Could not log out: '+e.message}finally{b.disabled=false}};$('#retrySave').onclick=()=>queue?.flush().catch(()=>{});$('#importLegacy').onclick=()=>{if(window.wsmsLoadLegacy?.())$('#legacyNotice').hidden=true};$('#dismissLegacy').onclick=()=>{$('#legacyNotice').hidden=true};window.addEventListener('beforeunload',e=>{if(queue?.dirty){e.preventDefault();e.returnValue=''}});
(async()=>{setBusy(true);try{const user=await authProvider.currentUser();await enter(user)}catch(e){if(e.status!==401)message(e.message);else routeToLogin()}finally{window.wsmsRouting=false;$('#application').inert=false;setBusy(false)}})();

function requestedPageRoute(){const loc=window.location;if(!loc)return {type:'warehouses'};let route=parsePageRoute(loc.pathname,loc.search);if(route.type==='login'){const next=new URL(safeNextPath(route.next),'https://wsms.invalid');route=parsePageRoute(next.pathname,next.search)}return route;}
function routeToLogin(){const loc=window.location;if(!loc||!window.history?.replaceState)return;const current=loc.pathname+loc.search,next=safeNextPath(current);if(loc.pathname!=='/login')window.history.replaceState({},'','/login'+(next==='/warehouses'?'':'?next='+encodeURIComponent(next)));}
async function navigatePageRoute(route=requestedPageRoute()){const generation=++routeGeneration;window.wsmsRouting=true;$('#application').inert=true;$('#application').setAttribute('aria-busy','true');try{if(route.type==='warehouse'){if(window.wsmsSession?.warehouse?.id!==route.warehouseId){const ok=await openWarehouseView(route.warehouseId,route.page,{isCurrent:()=>generation===routeGeneration});if(!ok){if(generation===routeGeneration){const error=$('#warehouseSwitchError').textContent;window.wsmsShowPage('warehouses');await window.wsmsRefreshWarehouses?.();$('#warehouseListError').textContent=error;}return}}if(generation===routeGeneration)window.wsmsApplyRoute(route);}else{window.wsmsShowPage('warehouses');await window.wsmsRefreshWarehouses?.();if(route.type==='notfound')$('#warehouseListError').textContent='This page was not found. Choose a warehouse to continue.';}}finally{if(generation===routeGeneration){window.wsmsRouting=false;$('#application').inert=false;$('#application').setAttribute('aria-busy','false');window.wsmsSyncRoute?.(true)}}}
window.addEventListener('popstate',()=>{if(window.wsmsSession?.user)navigatePageRoute().catch(e=>{$('#warehouseListError').textContent=e.message})});
